/* Hearth's chat: your prompt a soft card in a warm tint with a gentle outline and generous
   corners, tool cards like a ruled page, quiet secondary text warmed toward the accent.
   Only cmux.agentPane.style/1 tokens (schemas/agent-pane/style-tokens.json), on :root: paint, so
   nothing in the transcript moves when this applies or reloads. Every color is made from the
   theme's own, so it reads over Hearth and Hearth Dark and over any theme of your own. */
:root {
  --cv-user-bubble-tint: color-mix(in srgb, var(--agent-accent) 8%, transparent);
  --cv-user-bubble-edge: color-mix(in srgb, var(--agent-accent) 26%, transparent);
  --cv-user-bubble-radius: 14px;
  --cv-card-fill: color-mix(in srgb, var(--agent-accent) 5%, transparent);
  --cv-card-ring: color-mix(in srgb, var(--agent-accent) 18%, transparent);
  --cv-code-edge-fade: 32px;
  --cv-text-muted: color-mix(in srgb, color-mix(in srgb, var(--agent-text) 88%, var(--agent-accent)) 84%, transparent);
  /* Tool rows and "Worked for" draw --cv-activity-text (the stock 58% of the text): this look's muted
     ink instead, so they hold 4.5:1 on its paper (golden-look-contrast-N.test.ts). */
  --cv-activity-text: var(--cv-text-muted);
  --cv-text-dim: color-mix(in srgb, color-mix(in srgb, var(--agent-text) 88%, var(--agent-accent)) 74%, transparent);
  --cv-link: color-mix(in srgb, var(--agent-accent) 72%, var(--agent-text));
  --agent-link: color-mix(in srgb, var(--agent-accent) 72%, var(--agent-text));
}

